import json
import importlib.util

workspace = '/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs'

# All demo data
task_path = '/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-000641e2.json'
with open(task_path) as f:
    task = json.load(f)

print("Demo pairs:")
for i, pair in enumerate(task['demo_pairs']):
    print(f"\nDemo {i}: Input shape={len(pair['input'])}x{len(pair['input'][0])}")
    for j, (r_in, r_out) in enumerate(zip(pair['input'], pair['output'])):
        diff_cols = [k for k, (e, p) in enumerate(zip(r_in, r_out)) if e != p]
        if diff_cols:
            print(f"  Row {j}: {r_in[:6]}... → {r_out[:6]}... (changed at cols {diff_cols[:3]}...)")
        else:
            print(f"  Row {j}: no changes")

# Analyze the pattern
print("\n=== Pattern analysis ===")
for i, pair in enumerate(task['demo_pairs']):
    for j, (r_in, r_out) in enumerate(zip(pair['input'], pair['output'])):
        # Count distinct colors in row
        colors_in = set(r_in)
        changed = [k for k, (e, p) in enumerate(zip(r_in, r_out)) if e != p]

        if colors_in == {r_in[0]}:  # Uniform row
            print(f"D{i}:{j} UNIFORM({r_in[0]}) - no changes")
        else:  # Mixed row
            if not changed:
                print(f"D{i}:{j} MIXED({r_in[:4]}...) - NO CHANGES (unexpected?)")
            elif changed == [0]:
                print(f"D{i}:{j} MIXED({r_in[:4]}...) - only first cell changed (to 1)")
            elif len(changed) == 1 and changed[0] > 0:
                first_color = r_in[0]
                first_run_end = 0
                for k, c in enumerate(r_in):
                    if c != first_color:
                        first_run_end = k
                        break
                print(f"D{i}:{j} MIXED - first run (0 to {first_run_end}) preserved, rest changed")
            else:
                print(f"D{i}:{j} MIXED with {len(changed)} changes")
